// Generated by AI (UnitTest MCP)
import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, rmSync, statSync, utimesSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";

import {
  acquireSweepLock,
  applySweep,
  describeSweep,
  dueForSweep,
  owningWorktree,
  readSweepFreshness,
  readSweepState,
  SWEEP_CRITICAL_SCRIPTS,
  SWEEP_INTERVAL_MS,
  summariseSkips,
  sweepIfDue,
  writeSweepState,
} from "./artefact-sweep.mjs";

const HOUR = 60 * 60 * 1000;
const NOW = 1_700_000_000_000;

const scratch = () => mkdtempSync(join(tmpdir(), "artefact-sweep-"));

/** A checkout whose safety-critical scripts match origin/main. */
const CURRENT = () => ({ current: true, reason: null });

const cache = (over = {}) => ({
  kind: "cargo-debug",
  rel: "target/debug",
  path: "C:/Repos/MindLeak-x/target/debug",
  branch: "feat/x",
  bare: false,
  dirty: false,
  landed: true,
  owner: null,
  building: false,
  modifiedAt: NOW - 7 * 24 * HOUR,
  bytes: 100,
  files: 5,
  ...over,
});

// --- cadence --------------------------------------------------------------

test("a sweep that has never run is due, so an upgrade audits immediately", () => {
  assert.equal(dueForSweep(null, NOW), true);
  assert.equal(dueForSweep(undefined, NOW), true);
  assert.equal(dueForSweep(Number.NaN, NOW), true);
});

test("a sweep is not due again until the interval has passed", () => {
  assert.equal(dueForSweep(NOW - HOUR, NOW, SWEEP_INTERVAL_MS), false);
  assert.equal(dueForSweep(NOW - 7 * HOUR, NOW, SWEEP_INTERVAL_MS), true);
});

test("the last-run timestamp survives a restart", () => {
  const dir = scratch();
  try {
    assert.equal(readSweepState(dir).lastRunAt, null);
    writeSweepState(dir, { lastRunAt: NOW });
    assert.equal(readSweepState(dir).lastRunAt, NOW);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("an unreadable state file reads as never run rather than as up to date", () => {
  // The safe direction: an extra audit costs a disk walk, a skipped one costs
  // unbounded growth.
  const dir = scratch();
  try {
    assert.equal(readSweepState(join(dir, "does-not-exist")).lastRunAt, null);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("a dry run does not mark the sweep as done", () => {
  // Regression: sweepIfDue recorded lastRunAt whatever it did, so asking what
  // would happen suppressed the next real sweep for a whole interval — the one
  // command a cautious operator runs first would quietly stop the work.
  const dir = scratch();
  const report = {
    planned: 1,
    bytes: 1,
    files: 1,
    candidates: 1,
    skips: [],
    applied: null,
  };
  try {
    const dry = sweepIfDue({
      anchor: dir,
      commonDir: dir,
      apply: false,
      now: NOW,
      force: true,
      checkFreshness: CURRENT,
      run: () => report,
    });
    assert.equal(dry.ran, true);
    assert.equal(readSweepState(dir).lastRunAt, null);

    const wet = sweepIfDue({
      anchor: dir,
      commonDir: dir,
      apply: true,
      now: NOW,
      force: true,
      checkFreshness: CURRENT,
      run: () => report,
    });
    assert.equal(wet.ran, true);
    assert.equal(readSweepState(dir).lastRunAt, NOW);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("a sweep that is not due does not run, and releases nothing it did not take", () => {
  const dir = scratch();
  try {
    writeSweepState(dir, { lastRunAt: NOW });
    let ran = false;
    const outcome = sweepIfDue({
      anchor: dir,
      commonDir: dir,
      now: NOW + 60_000,
      run: () => {
        ran = true;
        return {};
      },
    });
    assert.equal(outcome.ran, false);
    assert.equal(outcome.reason, "not due");
    assert.equal(ran, false);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("a second sweeper does not run while the first holds the lock", () => {
  const dir = scratch();
  try {
    acquireSweepLock(dir, NOW);
    let ran = false;
    const outcome = sweepIfDue({
      anchor: dir,
      commonDir: dir,
      now: NOW,
      force: true,
      checkFreshness: CURRENT,
      run: () => {
        ran = true;
        return {};
      },
    });
    assert.equal(outcome.ran, false);
    assert.match(outcome.reason, /another sweep/);
    assert.equal(ran, false);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("an unreachable GitHub stops the run rather than sweeping every branch", () => {
  // Fail closed: an unknown pull-request set must not read as "no branch has
  // one", which is exactly the caches a reviewer is about to need.
  const dir = scratch();
  try {
    const outcome = sweepIfDue({
      anchor: dir,
      commonDir: dir,
      apply: true,
      now: NOW,
      force: true,
      checkFreshness: CURRENT,
      run: () => ({
        skippedRun: "GitHub was unreachable, so open pull requests are unknown",
      }),
    });
    assert.equal(outcome.ran, false);
    assert.match(outcome.reason, /unreachable/);
    assert.equal(readSweepState(dir).lastRunAt, null);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

// --- the stale-checkout refusal -------------------------------------------

test("a stale checkout does not sweep, and says which file went stale", () => {
  // Regression: worktree-reclaim.mjs refused to run from a stale checkout and
  // this, the unattended path, did not -- so the deliberate CLI was guarded and
  // the automatic one was not. Measured: PR #435 taught the sweep to spare the
  // fleet host's build output, and a sweep running from a pre-#435 `scripts/`
  // deleted it again anyway, leaving canonical-push unable to reach the ledger.
  const dir = scratch();
  try {
    let ran = false;
    const outcome = sweepIfDue({
      anchor: dir,
      commonDir: dir,
      apply: true,
      now: NOW,
      force: true,
      checkFreshness: () => ({
        current: false,
        reason: "scripts/worktree-reclaim.mjs differs from origin/main",
      }),
      run: () => {
        ran = true;
        return {};
      },
    });
    assert.equal(ran, false);
    assert.deepStrictEqual(outcome, {
      ran: false,
      reason:
        "stale checkout: scripts/worktree-reclaim.mjs differs from origin/main",
    });
    // A refused run is not a completed one: it must not suppress the next.
    assert.equal(readSweepState(dir).lastRunAt, null);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("the freshness check runs before the lock is taken", () => {
  // A sweeper that is about to be refused must not queue behind the fleet-wide
  // lock to find that out. Holding the lock first makes the order observable:
  // check-then-lock reports staleness, lock-then-check reports contention and
  // never mentions the stale rules at all.
  const dir = scratch();
  try {
    acquireSweepLock(dir, NOW);
    const outcome = sweepIfDue({
      anchor: dir,
      commonDir: dir,
      now: NOW,
      force: true,
      checkFreshness: () => ({ current: false, reason: "stale" }),
      run: () => ({}),
    });
    assert.deepStrictEqual(outcome, {
      ran: false,
      reason: "stale checkout: stale",
    });
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("an origin that cannot be fetched reads as stale, not as current", () => {
  // Fail closed. "I could not check" is not evidence of being up to date, and
  // the offline case is exactly when a long-lived watcher has drifted furthest.
  const freshness = readSweepFreshness("/anywhere", {
    git: (args) =>
      args[0] === "fetch"
        ? { ok: false, out: "no route to host" }
        : { ok: true },
  });
  assert.deepStrictEqual(freshness, {
    current: false,
    reason: "could not fetch origin before checking this script's version",
  });
});

test("stale imported rules are stale, even when the sweep itself is current", () => {
  // The selection rules live in worktree-reclaim.mjs and are imported, so a
  // current sweep on top of stale rules deletes by stale rules -- and looks
  // entirely healthy doing it. Being current is a property of the pair.
  const freshness = readSweepFreshness("/anywhere", {
    git: (args) => ({
      ok: args[0] !== "diff" || args.at(-1) !== "scripts/worktree-reclaim.mjs",
    }),
  });
  assert.deepStrictEqual(freshness, {
    current: false,
    reason: "scripts/worktree-reclaim.mjs differs from origin/main",
  });
});

test("a checkout matching origin/main on both scripts is current", () => {
  const asked = [];
  const freshness = readSweepFreshness("/anywhere", {
    git: (args) => {
      asked.push(args.join(" "));
      return { ok: true };
    },
  });
  assert.deepStrictEqual(freshness, { current: true, reason: null });
  assert.deepStrictEqual(asked, [
    "fetch origin --quiet --prune",
    ...SWEEP_CRITICAL_SCRIPTS.map(
      (script) => `diff --quiet origin/main -- ${script}`,
    ),
  ]);
});

// --- the fleet-wide lock --------------------------------------------------

test("only one sweeper holds the lock at a time", () => {
  const dir = scratch();
  try {
    const first = acquireSweepLock(dir, NOW);
    assert.equal(first.held, true);
    const second = acquireSweepLock(dir, NOW);
    assert.equal(second.held, false);
    assert.match(second.reason, /another sweep/);
    first.release();
    assert.equal(acquireSweepLock(dir, NOW).held, true);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("a lock abandoned by a killed process is broken on age alone", () => {
  const dir = scratch();
  try {
    const held = acquireSweepLock(dir, NOW);
    assert.equal(held.held, true);
    // Age the lock rather than inspecting a pid: pid reuse makes that check
    // wrong precisely when it matters.
    const lock = join(dir, "artefact-sweep.lock");
    const old = new Date(NOW - 90 * 60 * 1000);
    utimesSync(lock, old, old);
    const taken = acquireSweepLock(dir, NOW, 30 * 60 * 1000);
    assert.equal(taken.held, true);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("a fresh lock held by a live sweeper is never broken", () => {
  const dir = scratch();
  try {
    acquireSweepLock(dir, NOW);
    const denied = acquireSweepLock(dir, NOW + 60_000, 30 * 60 * 1000);
    assert.equal(denied.held, false);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

// --- apply ----------------------------------------------------------------

test("apply deletes exactly the planned directories and nothing else", () => {
  const removed = [];
  const plan = [
    cache({ path: "/a/target/debug" }),
    cache({ path: "/b/target/debug" }),
  ];
  const result = applySweep(plan, {
    now: NOW,
    revalidate: (c) => c,
    remove: (path) => removed.push(path),
  });
  assert.deepEqual(removed, ["/a/target/debug", "/b/target/debug"]);
  assert.equal(result.removed.length, 2);
  assert.equal(result.bytes, 200);
  assert.equal(result.files, 10);
});

test("a directory that stopped being eligible during the walk is abandoned, not deleted", () => {
  // A plan is a statement about the past: a tree idle when the walk started can
  // be building by the time the walk ends.
  const removed = [];
  const result = applySweep([cache({ path: "/a/target/debug" })], {
    now: NOW,
    revalidate: (c) => ({ ...c, building: true }),
    remove: (path) => removed.push(path),
  });
  assert.deepEqual(removed, []);
  assert.equal(result.removed.length, 0);
  assert.equal(result.abandoned.length, 1);
  assert.match(result.abandoned[0].reason, /no longer eligible/);
});

test("facts that cannot be re-read fail closed", () => {
  const removed = [];
  const result = applySweep([cache()], {
    now: NOW,
    revalidate: () => null,
    remove: (path) => removed.push(path),
  });
  assert.deepEqual(removed, []);
  assert.match(result.abandoned[0].reason, /could not be re-read/);
});

// --- attribution ----------------------------------------------------------

test("a sibling worktree's cache is never attributed to the bare host", () => {
  // `MindLeak` is a string prefix of `MindLeak-artifactid`, and the bare host is
  // the one place a misattribution would sweep target/release out from under the
  // running servers.
  const worktrees = [
    { path: "C:/Repos/MindLeak", bare: true },
    { path: "C:/Repos/MindLeak-artifactid", bare: false },
  ];
  const owner = owningWorktree(
    worktrees,
    "C:/Repos/MindLeak-artifactid/target/release",
  );
  assert.equal(owner.path, "C:/Repos/MindLeak-artifactid");
});

test("the bare host still owns its own cache", () => {
  const worktrees = [
    { path: "C:/Repos/MindLeak", bare: true },
    { path: "C:/Repos/MindLeak-artifactid", bare: false },
  ];
  assert.equal(
    owningWorktree(worktrees, "C:/Repos/MindLeak/target/debug").path,
    "C:/Repos/MindLeak",
  );
});

test("a path inside no worktree owns nothing", () => {
  assert.equal(
    owningWorktree(
      [{ path: "C:/Repos/MindLeak" }],
      "D:/elsewhere/target/debug",
    ),
    null,
  );
});

// --- reporting ------------------------------------------------------------

test("skips are collapsed into counts, commonest first", () => {
  const summary = summariseSkips([
    { reason: "uncommitted or untracked changes" },
    { reason: "a build is running here" },
    { reason: "uncommitted or untracked changes" },
  ]);
  assert.deepEqual(summary[0], {
    reason: "uncommitted or untracked changes",
    count: 2,
  });
  assert.equal(summary.length, 2);
});

test("a dry run says it reclaimed nothing, and an apply says what it took", () => {
  const dry = describeSweep({
    planned: 2,
    bytes: 2 * 1024 ** 3,
    files: 9,
    candidates: 5,
    skips: [],
    applied: null,
  });
  assert.match(dry, /reporting only/);
  assert.match(dry, /2\.00 GiB/);

  const wet = describeSweep({
    planned: 2,
    bytes: 0,
    files: 0,
    candidates: 5,
    skips: [],
    applied: { removed: [1, 2], abandoned: [], bytes: 1024 ** 3, files: 4 },
  });
  assert.match(wet, /reclaimed 1\.00 GiB across 2 directories/);
});

test("the report names how many directories each rule held back", () => {
  const text = describeSweep({
    planned: 0,
    bytes: 0,
    files: 0,
    candidates: 3,
    skips: [{ reason: "a build is running here", count: 3 }],
    applied: null,
  });
  // A refused directory must never read as one the tool failed to notice.
  assert.match(text, /3\s+a build is running here/);
});
